struct VSOut { float4 pos : SV_POSITION; float2 uv : TEXCOORD0; };

float4 PSBright(VSOut i) : SV_Target
{
    float2 uv = i.uv;
    float t = time_sim_ms * 0.001;
    float2 center = float2(0.5 + 0.2 * sin(t), 0.5 + 0.2 * cos(t * 0.7));
    float d = length(uv - center);
    float brightness = 0.03 / (d * d + 0.01);
    float3 color = float3(1.0, 0.8, 0.3) * brightness;
    float lum = dot(color, float3(0.2126, 0.7152, 0.0722));
    if (lum < 1.0) color = float3(0, 0, 0);
    return float4(color, 1.0);
}

