[[vk::combinedImageSampler]] [[vk::binding(0, 2)]]
Texture2D brightTex : register(t0, space2);
[[vk::combinedImageSampler]] [[vk::binding(0, 2)]]
SamplerState brightSamp : register(s0, space2);

struct VSOut { float4 pos : SV_POSITION; float2 uv : TEXCOORD0; };

float4 PSComposite(VSOut i) : SV_Target
{
    float2 uv = i.uv;
    float t = time_sim_ms * 0.001;

    float2 center = float2(0.5 + 0.2 * sin(t), 0.5 + 0.2 * cos(t * 0.7));
    float d = length(uv - center);
    float3 scene = float3(0.05, 0.05, 0.08) + float3(1.0, 0.8, 0.3) * 0.03 / (d * d + 0.01) * 0.3;

    float3 bloom = float3(0, 0, 0);
    for (int x = -4; x <= 4; x++) {
        for (int y = -4; y <= 4; y++) {
            float2 off = float2(x, y) / float2(resolution_x, resolution_y) * 4.0;
            bloom += brightTex.Sample(brightSamp, uv + off).rgb;
        }
    }
    bloom /= 81.0;

    float3 final_color = scene + bloom * 0.5;
    return float4(final_color, 1.0);
}
